import json, sys
from collections import defaultdict

d = json.load\(sys.stdin\)['data']
days = d.get\('data', []\)

all_slots = []
for day in days:
    for slot in day.get\('slots', []\):
        bp = slot.get\('blueprint'\)
        if bp:
            all_slots.append\({
                'date': day['date'],
                'time': slot['time'],
                'niche': slot.get\('niche_id', '?'\),
                'status': slot['status'],
                'bp_id': bp.get\('id'\),
                'hook': \(bp.get\('hook_text'\) or ''\)[:50],
                'candidate_id': bp.get\('candidate_id', ''\),
            }\)

print\(f'Total scheduled slots with blueprints: {len\(all_slots\)}'\)
print\(\)

# Check for duplicate blueprint IDs
id_counts = defaultdict\(list\)
for s in all_slots:
    id_counts[s['bp_id']].append\(f\\"{s['date']} {s['time']} {s['niche']}\\"\)

id_dupes = {k: v for k, v in id_counts.items\(\) if len\(v\) > 1}
if id_dupes:
    print\(f'DUPLICATE BLUEPRINT IDs in schedule: {len\(id_dupes\)}'\)
    for bp_id, slots in id_dupes.items\(\):
        hook = next\(s['hook'] for s in all_slots if s['bp_id'] == bp_id\)
        print\(f'  id={bp_id} \\"{hook}\\" appears in:'\)
        for slot in slots:
            print\(f'    {slot}'\)
    print\(\)
else:
    print\('No duplicate blueprint IDs in schedule.'\)

# Check for duplicate hooks \(same content, different IDs\)
hook_counts = defaultdict\(list\)
for s in all_slots:
    hook_key = \(s['hook'].lower\(\), s['niche']\)
    hook_counts[hook_key].append\(f\\"id={s['bp_id']} {s['date']} {s['time']}\\"\)

hook_dupes = {k: v for k, v in hook_counts.items\(\) if len\(v\) > 1}
if hook_dupes:
    print\(f'DUPLICATE HOOKS in schedule: {len\(hook_dupes\)}'\)
    for \(hook, niche\), slots in hook_dupes.items\(\):
        print\(f'  \\"{hook}\\" \({niche}\):'\)
        for slot in slots:
            print\(f'    {slot}'\)
else:
    print\('No duplicate hooks in schedule.'\)

# Check for same niche on same date \(1 post/niche/day rule\)
