for s in all_slots:
    date_niche[\(s['date'], s['niche']\)].append\(f\\"id={s['bp_id']} {s['time']} \\\\\\"{s['hook']}\\\\\\"\\"\)

day_dupes = {k: v for k, v in date_niche.items\(\) if len\(v\) > 1}
